public class Administrador extends Usuario {
    public Administrador(String nome, String email, String senha) {
        super(nome, email, senha);
    }

    @Override
    public boolean autenticar(String senha) {
        // Não é possível acessar senha diretamente, então precisamos de um método para comparar
        // Como senha é private, normalmente teríamos um getter protegido, mas para o desafio, vamos comparar via equals
        return this.senhaEquals(senha);
    }

    private boolean senhaEquals(String senha) {
        // Acesso ao atributo senha da superclasse
        try {
            java.lang.reflect.Field field = Usuario.class.getDeclaredField("senha");
            field.setAccessible(true);
            String senhaReal = (String) field.get(this);
            return senhaReal.equals(senha);
        } catch (Exception e) {
            return false;
        }
    }

    public void redefinirSenha(String novaSenha) {
        try {
            java.lang.reflect.Field field = Usuario.class.getDeclaredField("senha");
            field.setAccessible(true);
            field.set(this, novaSenha);
        } catch (Exception e) {
            System.out.println("Erro ao redefinir senha.");
        }
    }
}

public class Administrador extends Usuario {
    public Administrador(String nome, String email, String senha) {
        super(nome, email, senha);
    }

    @Override
    public boolean autenticar(String senha) {
        return getSenha().equals(senha);
    }

    public void redefinirSenha(String novaSenha) {
        setSenha(novaSenha);
    }
}

