public class Main {
    public static void main(String[] args) {
        System.out.println("Hello, World!");

        // Teste da classe Produto
        Produto p1 = new Produto("Mouse", 59.90, 10);
        Produto p2 = new Produto("Teclado", 129.90);

        p1.exibirResumo();
        System.out.println("---");
        p2.exibirResumo();
        System.out.println("Adicionando 5 ao estoque do teclado...");
        p2.adicionarEstoque(5);
        p2.exibirResumo();
        System.out.println("Vendendo 3 mouses...");
        boolean venda = p1.vender(3);
        System.out.println("Venda realizada? " + venda);
        p1.exibirResumo();
        System.out.println("Tentando vender 20 teclados...");
        boolean venda2 = p2.vender(20);
        System.out.println("Venda realizada? " + venda2);
        p2.exibirResumo();
    }
}

public class Produto {
    private String nome;
    private double preco;
    private int estoque;

    // Construtor que define todos os atributos
    public Produto(String nome, double preco, int estoque) {
        this.nome = nome;
        this.preco = preco;
        this.estoque = estoque;
    }

    // Construtor que define apenas nome e preco, estoque inicial = 0
    public Produto(String nome, double preco) {
        this(nome, preco, 0);
    }

    // Método para adicionar ao estoque
    public void adicionarEstoque(int quantidade) {
        if (quantidade > 0) {
            this.estoque += quantidade;
        }
    }

    // Método para vender produtos
    public boolean vender(int quantidade) {
        if (quantidade > 0 && this.estoque >= quantidade) {
            this.estoque -= quantidade;
            return true;
        }
        return false;
    }

    // Método para exibir resumo do produto
    public void exibirResumo() {
        System.out.println("Produto: " + nome);
        System.out.println("Preço: R$ " + preco);
        System.out.println("Estoque: " + estoque);
    }
}

public class SegurancaUtils {
    public static boolean validarSenhaForte(String senha) {
        if (senha == null || senha.length() <= 8) return false;
        boolean temNumero = false;
        for (char c : senha.toCharArray()) {
            if (Character.isDigit(c)) {
                temNumero = true;
                break;
            }
        }
        return temNumero;
    }
}

public class Sistema {
    public static void main(String[] args) {
        Administrador admin = new Administrador("Maria", "maria@email.com", "senha1234");

        // Teste de acesso direto aos atributos
        System.out.println("Acesso direto ao nome: " + admin.nome); // acessível
        // System.out.println(admin.email); // ERRO: protected se estiver em outro pacote
        // System.out.println(admin.senha); // ERRO: private

        // Teste de métodos
        admin.exibirUsuario();
        System.out.println("Autenticação correta: " + admin.autenticar("senha1234"));
        System.out.println("Autenticação incorreta: " + admin.autenticar("errada"));

        admin.redefinirSenha("novaSenha2025");
        System.out.println("Autenticação nova senha: " + admin.autenticar("novaSenha2025"));

        // Teste utilitário
        System.out.println("Senha forte? '12345678': " + SegurancaUtils.validarSenhaForte("12345678"));
        System.out.println("Senha forte? 'senha1234': " + SegurancaUtils.validarSenhaForte("senha1234"));
        System.out.println("Senha forte? 'forte2025!': " + SegurancaUtils.validarSenhaForte("forte2025!"));
    }
}

public abstract class Usuario {
    private String senha;
    protected String email;
    public String nome;

    public Usuario(String nome, String email, String senha) {
        this.nome = nome;
        this.email = email;
        this.senha = senha;
    }

    public abstract boolean autenticar(String senha);

    public final void exibirUsuario() {
        System.out.println("Nome: " + nome + " | Email: " + email);
    }
}

public abstract class Usuario {
    private String senha;
    protected String email;
    public String nome;

    public Usuario(String nome, String email, String senha) {
        this.nome = nome;
        this.email = email;
        this.senha = senha;
    }

    public abstract boolean autenticar(String senha);

    public final void exibirUsuario() {
        System.out.println("Nome: " + nome + " | Email: " + email);
    }

    public String getSenha() {
        return senha;
    }

    public void setSenha(String senha) {
        this.senha = senha;
    }
}

package desafio2;

public class MainDesafio2 {
    public static void main(String[] args) {
        // Funcionário 1: menos de 7 dias
        Reembolso r1 = new Reembolso("Carla", 5);
        double total1 = r1.calcularReembolso(150.0, 100.0, 135.0);
        r1.imprimirResumoReembolso(total1);

        // Funcionário 2: mais de 7 dias, com hospedagem
        Reembolso r2 = new Reembolso("João", 10);
        double total2 = r2.calcularReembolso(200.0, 120.0, 180.0);
        r2.imprimirResumoReembolso(total2);

        // Funcionário 3: mais de 7 dias, sem hospedagem
        Reembolso r3 = new Reembolso("Ana", 8);
        double total3 = r3.calcularReembolso(180.0, 90.0);
        r3.imprimirResumoReembolso(total3);
    }
}
